proc generatePythonBindings(bindings: seq[FFIBinding]): string =
  result = """# JAIDE v19 - Python FFI Bindings
# Auto-generated by meta/generator/ffi_generator.nim

import ctypes
from pathlib import Path

# Load PFR shared library
_lib_path = Path(__file__).parent / "pfr" / "lib" / "libpfr.so"
_pfr_lib = ctypes.CDLL(str(_lib_path))

"""

  for binding in bindings:
    let params = binding.parameters.mapIt(it.name & ": " & 
      case it.param_type:
        of "u32": "ctypes.c_uint32"
        of "u64": "ctypes.c_uint64"
        of "bool": "ctypes.c_bool"
        of "rawptr": "ctypes.c_void_p"
        of "cstring": "ctypes.c_char_p"
        of "ptr float32": "ctypes.POINTER(ctypes.c_float)"
        of "ptr u32": "ctypes.POINTER(ctypes.c_uint32)"
        of "usize": "ctypes.c_size_t"
        else: "ctypes.c_void_p").join(", ")

    let return_type = case binding.return_type:
      of "bool": "ctypes.c_bool"
      of "rawptr": "ctypes.c_void_p"
      of "void": "None"
      else: "ctypes.c_void_p"

    result.add &"""
# {binding.description}
_{binding.name} = _pfr_lib.{binding.name}
_{binding.name}.argtypes = [{params.replace(": ", ", ")}]
_{binding.name}.restype = {return_type}

def {binding.name}({params}):
    \"\"\"
    {binding.description}
    \"\"\"
    return _{binding.name}({binding.parameters.mapIt(it.name).join(", ")})

"""

