        of "u32": "UInt32"
        of "u64": "UInt64" 
        of "bool": "Bool"
        of "rawptr": "Ptr{Nothing}"
        of "cstring": "Cstring"
        of "ptr float32": "Ptr{Float32}"
        of "ptr u32": "Ptr{UInt32}"
        of "usize": "UInt"
        else: "Ptr{Nothing}").join(", ")

    let return_type = case binding.return_type:
      of "bool": "Bool"
      of "rawptr": "Ptr{Nothing}"
      of "void": "Nothing"
      else: "Ptr{Nothing}"

    result.add &"""
\"\"\"
    {binding.name}({params}) -> {return_type}

{binding.description}
\"\"\"
function {binding.name}({params})
    ccall((:{binding.name}, libpfr), {return_type}, ({binding.parameters.mapIt(
      case it.param_type:
        of "u32": "UInt32"
        of "u64": "UInt64"
        of "bool": "Bool" 
        of "rawptr": "Ptr{Nothing}"
        of "cstring": "Cstring"
        of "ptr float32": "Ptr{Float32}"
        of "ptr u32": "Ptr{UInt32}"
        of "usize": "UInt"
        else: "Ptr{Nothing}").join(", ")}), {binding.parameters.mapIt(it.name).join(", ")})
end

"""

  result.add "end # module JAIDEv19PFR"

