        else: "Ptr ()").join(" -> ")

    let return_type = case binding.return_type:
      of "bool": "CBool"
      of "rawptr": "Ptr ()"
      of "void": "IO ()"
      else: "Ptr ()"

    let haskell_name = binding.name.replace("_", "").capitalizeAscii()

    result.add &"""
-- | {binding.description}
foreign import ccall unsafe "{binding.name}"
  {haskell_name.toLowerAscii()} :: {params} -> {return_type}

"""

proc writeBindingsToFile(language: LanguageTarget, content: string) =
  let dir = case language:
    of ltPython: "meta/bindings/python"
    of ltJulia: "julia_core/bindings"
    of ltElixir: "elixir_api/lib/jaide_v19_api/pfr"
    of ltHaskell: "config/bindings"
    else: "meta/bindings/generated"

  let filename = case language:
    of ltPython: "pfr_bindings.py"
    of ltJulia: "PFRBindings.jl"
    of ltElixir: "bindings.ex"
    of ltHaskell: "PFRBindings.hs"
    else: "bindings.txt"

  createDir(dir)
  writeFile(dir / filename, content)
  echo &"Generated {language} bindings: {dir}/{filename}"

