  echo "Generating JAIDE v19 PFR FFI bindings for all languages..."

  # Generate bindings for each supported language
  writeBindingsToFile(ltPython, generatePythonBindings(PFR_FUNCTIONS))
  writeBindingsToFile(ltJulia, generateJuliaBindings(PFR_FUNCTIONS))
  writeBindingsToFile(ltElixir, generateElixirBindings(PFR_FUNCTIONS))
