// HTTP request parser
const HttpRequest = struct {
    method: []const u8,
    path: []u8,
    body: ?[]u8,
};

fn parseHttpRequest(request: []const u8, allocator: Allocator) !HttpRequest {
    var lines = std.mem.split(u8, request, "\r\n");
    const first_line = lines.next() orelse return error.InvalidRequest;

    var parts = std.mem.split(u8, first_line, " ");
    const method = parts.next() orelse return error.InvalidRequest;
    const path_raw = parts.next() orelse return error.InvalidRequest;

    const path = try allocator.dupe(u8, path_raw);

    // Find body (after double CRLF)
    const body_start = std.mem.indexOf(u8, request, "\r\n\r\n");
    const
